import { WritableStream, WritableStreamDefaultWriter, WritableStreamDefaultController, CountQueuingStrategy, ByteLengthQueuingStrategy, ReadableStream, TransformStream } from "node:stream/web";
import { out, deferred, result, launch } from "./helpers.js";

export function reportQueues() { launch(async () => {
  out("exports", ...[WritableStream, WritableStreamDefaultWriter, WritableStreamDefaultController, CountQueuingStrategy, ByteLengthQueuingStrategy].map((C) => C === globalThis[C.name]));
  const count = new CountQueuingStrategy({ highWaterMark: "2" });
  const bytes = new ByteLengthQueuingStrategy({ highWaterMark: 4 });
  out("strategies", count.highWaterMark, count.size(), bytes.highWaterMark, bytes.size(new Uint8Array(3)), count.size.name, bytes.size.name, count.size === new CountQueuingStrategy({ highWaterMark: 0 }).size, Object.prototype.toString.call(bytes));
  {
    const start = deferred(), first = deferred(), entered = deferred();
    const log = [];
    let controller;
    const sink = {
      start(c) { controller = c; log.push("start"); return start.promise; },
      write(chunk, c) {
        log.push(`write:${chunk}:${this === sink}:${c === controller}`);
        if (chunk === "a") { entered.resolve(); return first.promise; }
        return 42;
      },
      close() { log.push(`close:${this === sink}`); return "ignored"; },
    };
    const stream = new WritableStream(sink, count);
    const writer = new WritableStreamDefaultWriter(stream);
    const ready0 = writer.ready;
    const a = writer.write("a"), b = writer.write("b"), c = writer.write("c");
    const ready = writer.ready;
    let readyDone = false;
    ready.then(() => { readyDone = true; });
    sink.write = () => { throw new Error("changed algorithm"); };
    out("queued", log.join(","), writer.desiredSize, ready !== ready0, writer.ready === ready, stream.locked, writer instanceof WritableStreamDefaultWriter, controller instanceof WritableStreamDefaultController, Object.prototype.toString.call(controller));
    start.resolve(); await entered.promise;
    out("inflight", writer.desiredSize, readyDone, log.join(","));
    first.resolve();
    out("values", await a, await b, await c, await ready);
    await writer.close(); await writer.closed;
    out("closed", writer.desiredSize, log.join(","), await result(writer.write("late")));
    writer.releaseLock(); out("unlocked", stream.locked);
  }
  {
    const entered = deferred(), first = deferred();
    const stream = new WritableStream({ write(chunk) { if (chunk.byteLength === 3) { entered.resolve(); return first.promise; } } }, bytes);
    const w = stream.getWriter();
    const a = w.write(new Uint8Array(3)), b = w.write(new Uint8Array(2));
    out("byte-queued", w.desiredSize);
    await entered.promise;
    out("byte-inflight", w.desiredSize);
    const ready = w.ready;
    first.resolve(); await a; await ready;
    out("byte-drained", w.desiredSize);
    await b; await w.close(); out("byte-closed", w.desiredSize);
  }
  {
    const gate = deferred();
    const stream = new WritableStream({ start() { return gate.promise; } }, { highWaterMark: 0 });
    const w = stream.getWriter();
    let done = false;
    w.ready.then(() => { done = true; });
    await Promise.resolve();
    out("zero", w.desiredSize, done);
    const close = w.close(); await w.ready;
    out("close-ready", done, w.desiredSize);
    gate.resolve(); await close; await w.closed;
  }
  {
    let controller;
    const stream = new ReadableStream({ start(c) { controller = c; } }, bytes);
    controller.enqueue(new Uint8Array(3)); controller.enqueue(new Uint8Array(2));
    out("readable-queued", controller.desiredSize);
    const reader = stream.getReader();
    out("readable-first", (await reader.read()).value.byteLength, controller.desiredSize);
    await reader.read(); controller.close(); await reader.closed;
    out("readable-closed", controller.desiredSize);
  }
  {
    const filled = deferred(); let pulls = 0, controller;
    const stream = new ReadableStream({
      start(c) { controller = c; },
      pull(c) { pulls++; c.enqueue(pulls); if (pulls === 3) filled.resolve(); },
    }, new CountQueuingStrategy({ highWaterMark: 3 }));
    await filled.promise;
    out("pull-strategy", pulls, controller.desiredSize);
    await stream.cancel();
    let zeroPulls = 0;
    const zero = new ReadableStream({ pull(c) { zeroPulls++; c.enqueue("demand"); c.close(); } }, { highWaterMark: 0 });
    await Promise.resolve(); out("zero-pull", zeroPulls);
    const r = zero.getReader(); out("demand", (await r.read()).value, zeroPulls); await r.read();
  }
  {
    const start = deferred(), first = deferred(), entered = deferred();
    const log = [];
    const t = new TransformStream({
      start() { return start.promise; },
      async transform(v, c) { log.push(v); if (v === "a") { entered.resolve(); await first.promise; } c.enqueue(v); },
      flush(c) { c.enqueue("flush"); },
    }, count, new CountQueuingStrategy({ highWaterMark: 3 }));
    const w = t.writable.getWriter(), r = t.readable.getReader();
    const a = w.write("a"), b = w.write("b");
    out("transform-queued", w.desiredSize, log.length, t.writable instanceof WritableStream);
    start.resolve(); const read = r.read(); await entered.promise;
    out("transform-inflight", log.join(","), w.desiredSize);
    first.resolve(); out("transform-first", (await read).value); await a; await b;
    const close = w.close();
    const got = []; for (;;) { const next = await r.read(); if (next.done) break; got.push(next.value); }
    await close; out("transform-rest", got.join(","), log.join(","));
  }
  {
    let desired;
    const t = new TransformStream({ start(c) { desired = c.desiredSize; } });
    out("transform-default", desired); await t.writable.abort("cleanup");
  }
}); }
